#include <iostream>
#include <string>
#include <cctype>
#include <utility>

bool isFiveLetterPalindrome(const std::string& s) {
    if (s.length() != 5) return false;
    return (s[0] == s[4]) && (s[1] == s[3]);
}

bool isValidSSN(const std::string& ssn) {
    if (ssn.length() != 11) return false;
    for (int i = 0; i < 11; ++i) {
        if (i == 3 || i == 6) {
            if (ssn[i] != '-') return false;
        } else {
            if (!std::isdigit(static_cast<unsigned char>(ssn[i]))) return false;
        }
    }
    return true;
}

int main() {
    std::string word = "radar";
    std::string ssn1 = "232-23-5435";
    std::string ssn2 = "23-23-5435";

    std::cout << word << (isFiveLetterPalindrome(word) ? " is a palindrome" : " is not a palindrome") << "\n";
    std::cout << ssn1 << (isValidSSN(ssn1) ? " is a valid social security number" : " is an invalid social security number") << "\n";
    std::cout << ssn2 << (isValidSSN(ssn2) ? " is a valid social security number" : " is an invalid social security number") << "\n";

    std::string c1 = "Chicago", c2 = "Los Angeles", c3 = "Atlanta";
    if (c1 > c2) std::swap(c1, c2);
    if (c1 > c3) std::swap(c1, c3);
    if (c2 > c3) std::swap(c2, c3);
    std::cout << "Ordered: " << c1 << " " << c2 << " " << c3 << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <iomanip>

void decodeStudent(const std::string& code) {
    if (code.length() < 2) return;
    std::string major;
    if (code[0] == 'M') major = "Mathematics";
    else if (code[0] == 'C') major = "Computer Science";
    else if (code[0] == 'I') major = "Information Technology";
    else {
        std::cout << "Invalid major code\n";
        return;
    }

    std::string status;
    if (code[1] == '1') status = "Freshman";
    else if (code[1] == '2') status = "Sophomore";
    else if (code[1] == '3') status = "Junior";
    else if (code[1] == '4') status = "Senior";
    else {
        std::cout << "Invalid status code\n";
        return;
    }

    std::cout << major << " " << status << "\n";
}

int main() {
    decodeStudent("M1");
    decodeStudent("C3");
    decodeStudent("T3");
    decodeStudent("M7");

    std::string name = "Smith";
    double hours = 10.0;
    double rate = 9.75;
    double fedRate = 0.20;
    double stateRate = 0.09;

    double grossPay = hours * rate;
    double fedWithholding = grossPay * fedRate;
    double stateWithholding = grossPay * stateRate;
    double totalDeduction = fedWithholding + stateWithholding;
    double netPay = grossPay - totalDeduction;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "\nEmployee Name: " << name << "\n";
    std::cout << "Hours Worked: " << std::setprecision(1) << hours << "\n";
    std::cout << std::setprecision(2);
    std::cout << "Pay Rate: $" << rate << "\n";
    std::cout << "Gross Pay: $" << grossPay << "\n";
    std::cout << "Deductions:\n";
    std::cout << "  Federal Withholding (" << (fedRate * 100.0) << "%): $" << fedWithholding << "\n";
    std::cout << "  State Withholding (" << (stateRate * 100.0) << "%): $" << stateWithholding << "\n";
    std::cout << "  Total Deduction: $" << totalDeduction << "\n";
    std::cout << "Net Pay: $" << netPay << "\n";

    return 0;
}
